/**
 * @description Nightly batch that flags Open invoices whose Due Date has passed as Overdue.
 *              An active validation rule may reject saving an invoice as Overdue when
 *              Customer_Email__c is blank, so each record is saved independently and one
 *              failure never blocks the rest of the chunk. Job-level totals (updated, failed,
 *              overdue amount) are accumulated across all chunks via Database.Stateful and
 *              written to a single FB_Job_Summary__c record in finish().
 *
 *              The class is safe to invoke directly (null BatchableContext) for testing.
 */
public without sharing class OverdueInvoiceBatch implements Database.Batchable<sObject>, Database.Stateful {

    public static final String JOB_NAME = 'OverdueInvoiceBatch';

    /** Number of invoices updated across the whole job. */
    public Integer recordsUpdated = 0;

    /** Number of invoices that failed to save across the whole job. */
    public Integer recordsFailed = 0;

    /** Sum of Amount__c of the successfully updated invoices (blank amounts count as 0). */
    public Decimal overdueAmount = 0;

    /** No-argument constructor required for Database.executeBatch. */
    public OverdueInvoiceBatch() {
    }

    /**
     * @description Collects every Open invoice whose Due Date is strictly before today.
     * @param batchableContext Ignored; may be null when called directly in tests.
     * @return QueryLocator over the invoices to process.
     */
    public Database.QueryLocator start(Database.BatchableContext batchableContext) {
        return Database.getQueryLocator([
            SELECT Id, Name, Status__c, Due_Date__c, Amount__c, Customer_Email__c
            FROM FB_Invoice__c
            WHERE Status__c = 'Open'
              AND Due_Date__c < TODAY
        ]);
    }

    /**
     * @description Flags each invoice in the chunk as Overdue, saving records independently
     *              (Database.update with allOrNone = false) so a failed save, e.g. blocked by
     *              the blank-email validation rule, does not roll back the other records.
     *              Maintains the job-wide running totals.
     * @param batchableContext Ignored; may be null when called directly in tests.
     * @param scope Invoices queried with Id, Name, Status__c, Due_Date__c, Amount__c and Customer_Email__c.
     */
    public void execute(Database.BatchableContext batchableContext, List<FB_Invoice__c> scope) {
        if (scope == null || scope.isEmpty()) {
            return;
        }

        // Amounts per invoice Id, taken from the records passed into this chunk.
        Map<Id, Decimal> amountsById = new Map<Id, Decimal>();
        // Build the list of records to update with the new status.
        List<FB_Invoice__c> invoicesToUpdate = new List<FB_Invoice__c>();
        for (FB_Invoice__c invoice : scope) {
            if (invoice == null || invoice.Id == null) {
                continue;
            }
            amountsById.put(invoice.Id, invoice.Amount__c);
            invoicesToUpdate.add(new FB_Invoice__c(
                Id = invoice.Id,
                Status__c = 'Overdue'
            ));
        }

        if (invoicesToUpdate.isEmpty()) {
            return;
        }

        // Partial success: failures do not prevent other records in the chunk from saving.
        List<Database.SaveResult> saveResults = Database.update(invoicesToUpdate, false);

        // Accumulate the job-wide running totals (Database.Stateful keeps them across chunks).
        for (Integer i = 0; i < saveResults.size(); i++) {
            Database.SaveResult result = saveResults[i];
            if (result.isSuccess()) {
                recordsUpdated++;
                Decimal amount = amountsById.get(invoicesToUpdate[i].Id);
                if (amount != null) {
                    overdueAmount += amount;
                }
            } else {
                recordsFailed++;
            }
        }
    }

    /**
     * @description Inserts exactly one FB_Job_Summary__c record with the job name and the
     *              three job-wide totals. Uses Database.insert so an unexpected DML problem
     *              surfaces as a BatchJob failure rather than being silently swallowed.
     * @param batchableContext Ignored; may be null when called directly in tests.
     */
    public void finish(Database.BatchableContext batchableContext) {
        FB_Job_Summary__c summary = new FB_Job_Summary__c(
            Job_Name__c = JOB_NAME,
            Records_Updated__c = (recordsUpdated == null) ? 0 : recordsUpdated,
            Records_Failed__c = (recordsFailed == null) ? 0 : recordsFailed,
            Overdue_Amount__c = (overdueAmount == null) ? 0 : overdueAmount
        );
        insert summary;
    }
}
