/**
 * Invocable Apex action for Flow: finds an existing Contact by email.
 *
 * Design notes:
 * - Runs `with sharing` so results respect the running user's record access.
 * - Bulk-safe: performs at most ONE SOQL query per invocation regardless of
 *   how many requests Flow passes in (Flow batches up to 200 interviews).
 * - Email matching is case-insensitive and ignores leading/trailing spaces.
 * - If multiple contacts share an email, the contact with the earliest
 *   CreatedDate wins (query ordered by CreatedDate ASC; the map keeps the
 *   first contact seen for each email).
 * - Always returns exactly one Result per Request, in the same order.
 */
public with sharing class ContactLookupAction {

    public class Request {
        @InvocableVariable(required=true label='Email' description='Email address of the contact to find')
        public String email;
    }

    public class Result {
        @InvocableVariable(label='Contact Id' description='Id of the matching contact, or blank if not found')
        public Id contactId;

        @InvocableVariable(label='Found' description='True if a contact was found for the given email')
        public Boolean found;
    }

    @InvocableMethod(label='Find Contact by Email' description='Finds an existing contact by email (case-insensitive). Returns the contact with the earliest CreatedDate when several match.')
    public static List<Result> find(List<Request> requests) {
        List<Result> results = new List<Result>();

        if (requests == null || requests.isEmpty()) {
            return results;
        }

        // 1. Collect distinct, trimmed email values worth querying.
        //    Blank/null emails are skipped here; they will resolve to not found.
        Set<String> emailsToQuery = new Set<String>();
        for (Request req : requests) {
            String normalized = normalizeEmail(req == null ? null : req.email);
            if (normalized != null) {
                emailsToQuery.add(normalized);
            }
        }

        // 2. Single bulkified SOQL query. SOQL string comparisons on Email are
        //    case-insensitive, so this matches emails regardless of stored case.
        //    Ordering by CreatedDate ASC guarantees the earliest-created contact
        //    is seen first for each email; the map then keeps only that first one.
        Map<String, Id> contactIdByEmail = new Map<String, Id>();
        if (!emailsToQuery.isEmpty()) {
            for (Contact c : [
                SELECT Id, Email
                FROM Contact
                WHERE Email IN :emailsToQuery
                ORDER BY CreatedDate ASC
            ]) {
                String key = normalizeEmail(c.Email);
                if (key != null && !contactIdByEmail.containsKey(key)) {
                    contactIdByEmail.put(key, c.Id);
                }
            }
        }

        // 3. Build one Result per Request, preserving input order.
        for (Request req : requests) {
            Result res = new Result();
            String normalized = normalizeEmail(req == null ? null : req.email);
            if (normalized != null && contactIdByEmail.containsKey(normalized)) {
                res.contactId = contactIdByEmail.get(normalized);
                res.found = true;
            } else {
                res.contactId = null;
                res.found = false;
            }
            results.add(res);
        }

        return results;
    }

    /**
     * Normalizes an email for matching: trims surrounding whitespace and
     * lowercases for case-insensitive comparison. Returns null for blank input.
     */
    private static String normalizeEmail(String email) {
        if (email == null) {
            return null;
        }
        String trimmed = email.trim();
        if (trimmed == '') {
            return null;
        }
        return trimmed.toLowerCase();
    }
}
