/**
 * LeadImportService
 *
 * Bulk-safe, partial-success lead import service used by the trade-show lead
 * upload screen. Imports every lead that can be inserted, reporting per-row
 * errors for the ones that cannot be, without ever throwing for row-level
 * failures.
 *
 * Guarantees:
 *  - Exactly one DML statement per call (Database.insert with allOrNone=false).
 *  - Leads with a blank LeadSource are stamped with 'Web' before insert.
 *  - Duplicate emails within one call (case-insensitive, trimmed): only the
 *    first occurrence is sent to the database; later occurrences get a
 *    'Duplicate email in import: <email>' error and never reach the DML,
 *    even if the first occurrence itself fails to insert.
 *  - Leads without an email are never treated as duplicates.
 *  - Database rejections surface as that lead's error messages joined with '; '.
 *  - Result members are never null; runs with sharing enforced.
 */
public with sharing class LeadImportService {

    /** Result of an import call. Members are never null. */
    public class ImportResult {
        /** Number of leads successfully inserted. */
        public Integer successCount;
        /** Ids of the inserted leads, in input order. */
        public List<Id> insertedIds;
        /** Input position (0-based) -> error message. Successful leads have no key. */
        public Map<Integer, String> errorsByIndex;

        public ImportResult() {
            this.successCount = 0;
            this.insertedIds = new List<Id>();
            this.errorsByIndex = new Map<Integer, String>();
        }
    }

    /**
     * Imports the given leads with partial success semantics.
     *
     * @param leads the leads to import, in display order
     * @return an ImportResult; never null, and its members are never null
     */
    public static ImportResult importLeads(List<Lead> leads) {
        ImportResult result = new ImportResult();

        // Null or empty input: return the empty result immediately.
        if (leads == null || leads.isEmpty()) {
            return result;
        }

        // Records that pass pre-checks and will be sent to the database,
        // plus their original (0-based) input positions so results can be
        // mapped back after the DML.
        List<Lead> toInsert = new List<Lead>();
        List<Integer> toInsertPositions = new List<Integer>();

        // Emails already claimed by an earlier lead in this call.
        Set<String> seenEmails = new Set<String>();

        for (Integer i = 0; i < leads.size(); i++) {
            Lead lead = leads[i];

            if (lead == null) {
                result.errorsByIndex.put(i, 'Lead record is required.');
                continue;
            }

            // Duplicate detection: case-insensitive, whitespace-trimmed.
            // Leads without an email are never duplicates.
            String normalizedEmail = null;
            if (String.isNotBlank(lead.Email)) {
                normalizedEmail = lead.Email.trim().toLowerCase();
            }

            if (normalizedEmail != null) {
                if (seenEmails.contains(normalizedEmail)) {
                    // Not sent to the database; this holds even when the
                    // first lead with this email subsequently fails to insert.
                    result.errorsByIndex.put(i, 'Duplicate email in import: ' + normalizedEmail);
                    continue;
                }
                seenEmails.add(normalizedEmail);
            }

            // Stamp LeadSource = 'Web' where blank.
            if (String.isBlank(lead.LeadSource)) {
                lead.LeadSource = 'Web';
            }

            toInsert.add(lead);
            toInsertPositions.add(i);
        }

        // Single DML statement per call; partial success so one bad row
        // never blocks the others or throws.
        if (!toInsert.isEmpty()) {
            List<Database.SaveResult> saveResults = Database.insert(toInsert, false);

            for (Integer j = 0; j < saveResults.size(); j++) {
                Database.SaveResult saveResult = saveResults[j];
                Integer inputIndex = toInsertPositions[j];

                if (saveResult.isSuccess()) {
                    result.insertedIds.add(toInsert[j].Id);
                    result.successCount++;
                } else {
                    List<String> messages = new List<String>();
                    for (Database.Error err : saveResult.getErrors()) {
                        messages.add(err.getMessage());
                    }
                    result.errorsByIndex.put(inputIndex, String.join(messages, '; '));
                }
            }
        }

        return result;
    }
}
