/**
 * @description Re-rates up to 50,000 Accounts from AnnualRevenue via a chain of
 * Queueable jobs. Each execution processes at most 200 accounts (the first 200
 * Ids in its list) using exactly one SOQL query and one DML statement, then
 * enqueues a child job with the remaining Ids so the work continues in a chain.
 *
 * Rating rules:
 *   AnnualRevenue >= 1,000,000 -> 'Hot'
 *   AnnualRevenue >=   100,000 -> 'Warm'
 *   anything else (incl. null) -> 'Cold'
 *
 * Chaining depth note:
 *   50,000 accounts / 200 accounts per execution = 250 chained executions.
 *   The platform default maximum stack depth for chained Queueables is 50, so
 *   every enqueue in this chain is done with System.AsyncOptions raising the
 *   maximum stack depth. This also makes the full chain verifiable inside a
 *   single test between Test.startTest() and Test.stopTest(); chaining is
 *   intentionally NOT skipped in test context. Requires API v62.0+ (see the
 *   accompanying -meta.xml), which introduced AsyncOptions stack-depth control.
 */
public inherited sharing class AccountScoringJob implements Queueable {

    /** Max accounts processed per execution. */
    @TestVisible
    private static final Integer BATCH_SIZE = 200;

    /**
     * Maximum chained-queueable stack depth requested for this chain.
     * Worst case: ceil(50,000 / 200) = 250 executions. 1000 leaves headroom
     * and comfortably covers the full chain (the platform default is only 50).
     */
    @TestVisible
    private static final Integer MAX_CHAIN_DEPTH = 1000;

    /** Ids still to be processed by this job (and its children). */
    private final List<Id> accountIds;

    /**
     * @param accountIds Ids of the Accounts to rate. Null or empty lists are
     *        tolerated: the job simply does nothing.
     */
    public AccountScoringJob(List<Id> accountIds) {
        this.accountIds = (accountIds == null) ? new List<Id>() : accountIds;
    }

    /**
     * @description Entry point for Marketing's button. Enqueues the first job
     *          of the chain and returns its Queueable job Id.
     * @param accountIds Ids of the Accounts to rate (up to 50,000).
     * @return the job Id of the first Queueable, or null when the list is
     *         null or empty (nothing is enqueued in that case).
     */
    public static Id start(List<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return null;
        }
        return System.enqueueJob(
            new AccountScoringJob(accountIds),
            buildAsyncOptions()
        );
    }

    /**
     * @description Processes the first 200 Ids of this job's list, setting
     *          Rating from AnnualRevenue, then chains a child job with the
     *          remaining Ids (if any).
     */
    public void execute(QueueableContext context) {
        Integer size = accountIds.size();
        if (size == 0) {
            return;
        }

        Integer batchCount = Math.min(BATCH_SIZE, size);

        // First 200 Ids of the list (Apex List has no subList(), so copy manually).
        List<Id> batchIds = new List<Id>();
        for (Integer i = 0; i < batchCount; i++) {
            batchIds.add(accountIds[i]);
        }

        // One SOQL query per execution.
        Map<Id, Account> accounts = new Map<Id, Account>(
            [SELECT Id, AnnualRevenue FROM Account WHERE Id IN :batchIds WITH USER_MODE]
        );

        List<Account> toUpdate = new List<Account>();
        for (Id accountId : batchIds) {
            Account acc = accounts.get(accountId);
            // Skip Ids that no longer resolve (e.g. deleted Accounts).
            if (acc == null) {
                continue;
            }
            acc.Rating = rate(acc.AnnualRevenue);
            toUpdate.add(acc);
        }

        // One DML statement per execution.
        if (!toUpdate.isEmpty()) {
            Database.update(toUpdate, AccessLevel.USER_MODE);
        }

        // Chain the next job with the remaining Ids, if any.
        if (size > batchCount) {
            List<Id> remainingIds = new List<Id>();
            for (Integer i = batchCount; i < size; i++) {
                remainingIds.add(accountIds[i]);
            }
            System.enqueueJob(
                new AccountScoringJob(remainingIds),
                buildAsyncOptions()
            );
        }
    }

    /**
     * @description Maps AnnualRevenue to the Rating picklist value.
     * @param annualRevenue the Account's AnnualRevenue (may be null).
     * @return 'Hot', 'Warm' or 'Cold'.
     */
    @TestVisible
    private static String rate(Decimal annualRevenue) {
        if (annualRevenue == null) {
            return 'Cold';
        }
        if (annualRevenue >= 1000000) {
            return 'Hot';
        }
        if (annualRevenue >= 100000) {
            return 'Warm';
        }
        return 'Cold';
    }

    /**
     * @description Builds the AsyncOptions that raise the chained-queueable
     *          stack depth above the 50-job default so a chain of up to 250
     *          executions (50,000 accounts) can complete without a
     *          System.AsyncException. Available from API version 62.0 onward.
     * @return configured AsyncOptions instance.
     */
    private static System.AsyncOptions buildAsyncOptions() {
        System.AsyncOptions options = new System.AsyncOptions();
        options.setMaximumQueueableStackDepth(MAX_CHAIN_DEPTH);
        return options;
    }
}
