@isTest
private class OpportunityCleanupServiceTest {

    private static final Date CUTOFF = Date.newInstance(2024, 6, 30);
    private static final String OPEN_STAGE = 'Prospecting';
    private static final String CLOSED_WON = 'Closed Won';
    private static final String CLOSED_LOST = 'Closed Lost';

    private static fflib_ApexMocks mocks;
    private static IOpportunitiesSelector selectorMock;
    private static fflib_ISObjectUnitOfWork uowMock;

    private static void givenMocks() {
        mocks = new fflib_ApexMocks();
        selectorMock = (IOpportunitiesSelector) mocks.mock(IOpportunitiesSelector.class);
        uowMock = (fflib_ISObjectUnitOfWork) mocks.mock(fflib_ISObjectUnitOfWork.class);
        Application.Selector.setMock(selectorMock);
        Application.UnitOfWork.setMock(uowMock);
    }

    private static Opportunity newOpportunity(Id recordId, String stageName, Date closeDate) {
        return new Opportunity(
            Id = recordId,
            StageName = stageName,
            CloseDate = closeDate
        );
    }

    private static void givenSelectorReturns(Set<Id> opportunityIds, List<Opportunity> records) {
        mocks.startStubbing();
        mocks.when(selectorMock.selectById(opportunityIds)).thenReturn(records);
        mocks.stopStubbing();
    }

    @isTest
    static void testClosesOnlyStaleOpportunitiesAndCommitsWorkOnce() {
        // Given: a mix of stale, closed, boundary and future opportunities
        givenMocks();

        Id staleId1 = fflib_IDGenerator.generate(Opportunity.SObjectType);
        Id staleId2 = fflib_IDGenerator.generate(Opportunity.SObjectType);
        Id wonId = fflib_IDGenerator.generate(Opportunity.SObjectType);
        Id lostId = fflib_IDGenerator.generate(Opportunity.SObjectType);
        Id onCutoffId = fflib_IDGenerator.generate(Opportunity.SObjectType);
        Id futureId = fflib_IDGenerator.generate(Opportunity.SObjectType);
        Id nullDateId = fflib_IDGenerator.generate(Opportunity.SObjectType);

        Opportunity stale1 = newOpportunity(staleId1, OPEN_STAGE, CUTOFF.addDays(-1));
        Opportunity stale2 = newOpportunity(staleId2, 'Negotiation', CUTOFF.addDays(-30));
        Opportunity won = newOpportunity(wonId, CLOSED_WON, CUTOFF.addDays(-1));
        Opportunity lost = newOpportunity(lostId, CLOSED_LOST, CUTOFF.addDays(-1));
        Opportunity onCutoff = newOpportunity(onCutoffId, OPEN_STAGE, CUTOFF);
        Opportunity future = newOpportunity(futureId, 'Qualification', CUTOFF.addDays(1));
        Opportunity nullDate = newOpportunity(nullDateId, OPEN_STAGE, null);

        Set<Id> opportunityIds = new Set<Id>{
            staleId1, staleId2, wonId, lostId, onCutoffId, futureId, nullDateId
        };
        givenSelectorReturns(
            opportunityIds,
            new List<Opportunity>{ stale1, stale2, won, lost, onCutoff, future, nullDate }
        );

        // When
        Integer result = OpportunityCleanupService.closeStale(opportunityIds, CUTOFF);

        // Then: only the two stale opportunities are counted
        System.assertEquals(2, result, 'Only the two stale opportunities should be counted');

        // Stale opportunities are updated to Closed Lost with the lost reason
        System.assertEquals(CLOSED_LOST, stale1.StageName, 'Stale opportunity 1 stage should be Closed Lost');
        System.assertEquals(OpportunityCleanupService.LOST_REASON, stale1.Description, 'Stale opportunity 1 description should be the lost reason');
        System.assertEquals(CLOSED_LOST, stale2.StageName, 'Stale opportunity 2 stage should be Closed Lost');
        System.assertEquals(OpportunityCleanupService.LOST_REASON, stale2.Description, 'Stale opportunity 2 description should be the lost reason');

        // Closed opportunities are left alone, even with a past close date
        System.assertEquals(CLOSED_WON, won.StageName, 'Closed Won opportunity must not be modified');
