/**
 * Domain class for Opportunity, implementing the validation rules:
 *  1. Amount must not be negative (on insert and update).
 *  2. Amount cannot change on an opportunity that was already Closed Won
 *     before the update (on update only).
 *
 * All errors are raised per-record via the fflib_SObjectDomain error(message,
 * record, field) helper, so they are registered in fflib_SObjectDomain.Errors
 * (queryable in unit tests) and attached to the Amount field of the offending
 * record only. Both checks are bulk-safe and require no SOQL.
 */
public with sharing class Opportunities extends fflib_SObjectDomain
{
    private static final String STAGE_CLOSED_WON = 'Closed Won';

    public Opportunities(List<Opportunity> sObjectList)
    {
        super(sObjectList);
    }

    /**
     * Standard fflib constructable inner class, used by
     * fflib_SObjectDomain.triggerHandler to instantiate this domain.
     */
    public class Constructor implements fflib_SObjectDomain.IConstructable
    {
        public fflib_SObjectDomain construct(List<SObject> sObjectList)
        {
            return new Opportunities(sObjectList);
        }
    }

    /**
     * Validation hook invoked by the fflib domain framework.
     * Rule 1: Amount must not be negative on insert or update.
     */
    public override void onValidate()
    {
        // The framework also invokes this hook while processing deletes;
        // this rule only applies to insert and update.
        if (Trigger.isDelete)
        {
            return;
        }

        for (Opportunity record : (List<Opportunity>) Records)
        {
            if (record.Amount != null && record.Amount < 0)
            {
                error('Amount cannot be negative.', record, Opportunity.Amount);
            }
        }
    }

    /**
     * Before-update hook. The framework supplies the pre-update record values
     * (Trigger.oldMap in trigger context) as existingRecords, so the change
     * comparison needs no SOQL.
     * Rule 2: Amount cannot change on an opportunity that was already
     * Closed Won before this update. Closing as won and changing the amount
     * in the same update is allowed (the prior stage is not Closed Won).
     */
    public override void onBeforeUpdate(Map<Id, SObject> existingRecords)
    {
        if (existingRecords == null)
        {
            return;
        }

        for (Opportunity record : (List<Opportunity>) Records)
        {
            Opportunity existing = (Opportunity) existingRecords.get(record.Id);
            if (existing == null)
            {
                continue;
            }

            Boolean wasClosedWon = existing.StageName == STAGE_CLOSED_WON;
            Boolean amountChanged = record.Amount != existing.Amount;

            if (wasClosedWon && amountChanged)
            {
                error('Amount cannot change on a won opportunity.', record, Opportunity.Amount);
            }
        }
    }
}
