/**
 * @description Service responsible for creating onboarding Accounts together with
 *              their related Contacts in a single atomic unit of work.
 *
 *              All DML is delegated to a single fflib_SObjectUnitOfWork so that
 *              Accounts and Contacts are committed once, transactionally, with
 *              parent/child relationships resolved by the Unit of Work (no
 *              hand-written DML statements).
 *
 *              Bulk-safe: records are accumulated in memory and registered with
 *              the Unit of Work, which performs set-based inserts, so hundreds
 *              of contacts are handled in a single commit.
 *
 * @group       Services
 */
public inherited sharing class AccountOnboardingService
{
    /**
     * @description Creates one Account per map key and one Contact per last name
     *              in the corresponding value list. All records are inserted via
     *              a single fflib_SObjectUnitOfWork and committed exactly once.
     *
     * @param  contactLastNamesByAccountName Map of Account Name -> list of Contact
     *              LastNames to create under that Account. A null or empty map
     *              (or an input containing only empty lists) results in no DML.
     * @return      The newly created Accounts, with their Ids populated after
     *              commitWork(). Returns an empty list when nothing was created.
     */
    public static List<Account> createAccountsWithContacts(Map<String, List<String>> contactLastNamesByAccountName)
    {
        // Nothing to do: no DML, empty result.
        if (contactLastNamesByAccountName == null || contactLastNamesByAccountName.isEmpty())
        {
            return new List<Account>();
        }

        // Single Unit of Work covering both object types; commit happens once at the end.
        fflib_SObjectUnitOfWork uow = new fflib_SObjectUnitOfWork(
            new List<SObjectType>
            {
                Account.SObjectType,
                Contact.SObjectType
            }
        );

        List<Account> newAccounts = new List<Account>();

        for (String accountName : contactLastNamesByAccountName.keySet())
        {
            if (String.isBlank(accountName))
            {
                // Cannot create an Account without a meaningful name; skip safely.
                continue;
            }

            Account newAccount = new Account(Name = accountName);
            uow.registerNew(newAccount);
            newAccounts.add(newAccount);

            List<String> lastNames = contactLastNamesByAccountName.get(accountName);
            if (lastNames == null)
            {
                continue;
            }

            for (String lastName : lastNames)
            {
                if (String.isBlank(lastName))
                {
                    // Contact.LastName is required; skip blank entries to keep
                    // the whole unit of work from failing.
                    continue;
                }

                Contact newContact = new Contact(LastName = lastName);

                // Register the child first; the lookup to the (not yet inserted)
                // parent is resolved by the Unit of Work via registerRelationship,
                // keeping the parent/child linkage inside the same commit.
                uow.registerNew(newContact);
                uow.registerRelationship(newContact, Contact.AccountId, newAccount);
            }
        }

        if (newAccounts.isEmpty())
        {
            // No valid work was registered; avoid an empty commit.
            return newAccounts;
        }

        // Single transactional commit. The Unit of Work writes the Accounts,
        // then the Contacts, and stamps the generated Ids back onto the
        // in-memory Account instances, so the returned list has Ids populated.
        uow.commitWork();

        return newAccounts;
    }
}
