/**
 * Sends newly created Accounts to the ERP as customers.
 *
 * Callout endpoint : POST callout:ERP/api/customers  (Named Credential "ERP")
 * Request body     : JSON array with exactly ONE customer per request, so the
 *                    ERP team can trace every account on its own.
 * ERP response     : 202 Accepted. Error handling and retries are out of scope.
 *
 * Design notes:
 *  - enqueueNewAccounts() is the single entry point used by AccountTrigger.
 *    It performs the callouts synchronously (one request per account). Apex
 *    forbids synchronous callouts from a trigger context, so when invoked
 *    from the trigger the first attempt raises a CalloutException, which is
 *    caught and the work is transparently handed to Queueable jobs that run
 *    immediately after the DML transaction commits.
 *  - The async fallback is chunked: an Apex transaction allows at most 100
 *    callouts, so a marketplace batch of up to 200 accounts is split into
 *    chunks of at most 100 accounts, one Queueable job per chunk. This keeps
 *    the number of enqueued jobs (<= 3 for 200 accounts) far below the
 *    50-jobs-per-transaction limit while still sending one HTTP request per
 *    account for ERP-side traceability.
 *  - Within the Queueable, each callout is individually try/caught only so a
 *    single failing account does not abort the remaining accounts of the
 *    chunk. No retry logic (out of scope per ticket).
 */
public with sharing class ErpCustomerSync implements Queueable {

    @TestVisible
    private static final String ERP_ENDPOINT = 'callout:ERP/api/customers';

    // Governor limit: max 100 callouts per Apex transaction.
    @TestVisible
    private static final Integer MAX_CALLOUTS_PER_TRANSACTION = 100;

    /**
     * Entry point called by AccountTrigger (after insert).
     * Sends one ERP customer request per account.
     */
    public static void enqueueNewAccounts(List<Account> newAccounts) {
        // Guard against empty trigger firings.
        if (newAccounts == null || newAccounts.isEmpty()) {
            return;
        }

        Integer completed = 0;
        try {
            // Synchronous path: one request per account.
            for (Integer i = 0; i < newAccounts.size(); i++) {
                sendCustomer(newAccounts[i]);
                completed = i + 1;
            }
            // All callouts completed synchronously - nothing left to do.
            return;
        } catch (Exception e) {
            // Synchronous callouts are not allowed in this context
            // (e.g. invoked from a trigger, or after uncommitted DML).
            // Fall through to the asynchronous path below for the accounts
            // that have not been sent yet (all of them when invoked from a
            // trigger, since the first attempt fails immediately).
            System.debug(
                LoggingLevel.INFO,
                'ErpCustomerSync: synchronous callout not possible (' + e.getMessage() +
                '); falling back to Queueable.'
            );
        }

        enqueueAsyncChunks(newAccounts.subList(completed, newAccounts.size()));
    }

    /**
     * Queues the remaining accounts in chunks small enough to respect the
     * 100-callouts-per-transaction limit; one Queueable job per chunk.
     */
    private static void enqueueAsyncChunks(List<Account> remaining) {
        if (remaining == null || remaining.isEmpty()) {
            return;
        }
        for (Integer start = 0; start < remaining.size(); start += MAX_CALLOUTS_PER_TRANSACTION) {
            Integer end = Math.min(start + MAX_CALLOUTS_PER_TRANSACTION, remaining.size());
            System.enqueueJob(new ErpCustomerSync(remaining.subList(start, end)));
        }
    }

    /**
     * Queueable execution: one HTTP request per account. A chunk never
     * contains more than MAX_CALLOUTS_PER_TRANSACTION accounts.
     */
    public void execute(QueueableContext context) {
        for (Account acc : accounts) {
            try {
                sendCustomer(acc);
            } catch (Exception e) {
                // Out of scope per ticket: no retry, no error handling.
                // Isolate the failure so remaining accounts still get sent.
                System.debug(
                    LoggingLevel.ERROR,
                    'ERP customer sync failed for account ' + acc.Id + ': ' + e.getMessage()
                );
            }
        }
    }

    private static void sendCustomer(Account acc) {
        HttpRequest request = buildRequest(acc);
        new Http().send(request);
    }

    @TestVisible
    private static HttpRequest buildRequest(Account acc) {
        HttpRequest request = new HttpRequest();
        request.setEndpoint(ERP_ENDPOINT);
        request.setMethod('POST');
        request.setHeader('Content-Type', 'application/json');
        // Body is a JSON array containing exactly this one customer.
        request.setBody(JSON.serialize(new List<ErpCustomer>{ toErpCustomer(acc) }));
        request.setTimeout(60000);
        return request;
    }

    @TestVisible
    private static ErpCustomer toErpCustomer(Account acc) {
        ErpCustomer customer = new ErpCustomer();
        customer.salesforceId = acc.Id; // 18-character account Id (after insert)
        customer.name = acc.Name;
        // ERP expects null when BillingCountry is blank.
        customer.country = String.isNotBlank(acc.BillingCountry) ? acc.BillingCountry : null;
        return customer;
    }

    /**
     * Shape of the single-element JSON array expected by the ERP:
     * [{"salesforceId": "001...", "name": "Acme GmbH", "country": "Germany"}]
     */
    @TestVisible
    private class ErpCustomer {
        public String salesforceId;
        public String name;
        public String country;
    }
}
