trigger OpportunityTrigger on Opportunity (after insert, after update) {

    // Collect the distinct accounts that need a rating refresh so we can make a
    // single asynchronous call for the whole batch instead of one per record.
    // With CPQ inserting/updating 200 opportunities at a time, one future call
    // per opportunity would blow the 50 @future calls per transaction limit;
    // this way a 200-row batch costs exactly one future call.
    Set<Id> accountIds = new Set<Id>();

    for (Opportunity opp : Trigger.new) {
        if (opp.AccountId == null) {
            continue;
        }

        Boolean recalc;

        if (Trigger.isInsert) {
            recalc = true;
        } else {
            Opportunity oldOpp = Trigger.oldMap.get(opp.Id);
            recalc = oldOpp.StageName != opp.StageName
                || oldOpp.Amount != opp.Amount
                // The spec only names StageName and Amount, but if the
                // opportunity moved to a different account, the account it
                // left is also stale. Recalculate both.
                || oldOpp.AccountId != opp.AccountId;

            if (recalc && oldOpp.AccountId != null) {
                accountIds.add(oldOpp.AccountId);
            }
        }

        if (recalc) {
            accountIds.add(opp.AccountId);
        }
    }

    if (!accountIds.isEmpty()) {
        AccountRatingService.recalculate(accountIds);
    }
}
