/**
 * Queueable job that creates a CSAT survey Task for closed cases.
 *
 * Designed for bulk-safe operation:
 *  - The trigger hands it the full set of newly closed case IDs; this class
 *    splits them into chunks and enqueues one job per chunk. A naive
 *    "one job per case" design would hit the 50-Queueable-enqueues-per-
 *    transaction limit on bulk closes (uncatchable LimitException that rolls
 *    back the whole save).
 *  - Within a job, Tasks are inserted with partial success (allOrNone=false)
 *    and every failure is logged individually, so one bad case never affects
 *    the other cases in its chunk.
 *
 * Future growth (vendor survey integration) should be added in execute(),
 * keeping the trigger untouched.
 */
public inherited sharing class CaseSurveyJob implements Queueable {

    @TestVisible
    private static final Integer CASES_PER_JOB = 50;

    private final List<Id> caseIds;

    /**
     * @param caseIds IDs of newly closed cases to create CSAT tasks for.
     */
    public CaseSurveyJob(List<Id> caseIds) {
        this.caseIds = caseIds;
    }

    /**
     * Entry point used by CaseTrigger. Chunks the case IDs and enqueues one
     * Queueable job per chunk, always respecting the per-transaction limit
     * on enqueued Queueable jobs (Limits.getLimitQueueableJobs(), typically 50).
     */
    public static void enqueueForCases(List<Id> caseIds) {
        if (caseIds == null || caseIds.isEmpty()) {
            return;
        }

        Integer size = caseIds.size();
        Integer remainingJobs = Limits.getLimitQueueableJobs() - Limits.getQueueableJobs();

        // Normal volume: fixed, comfortably sized chunks (200 cases -> 4 jobs).
        Integer chunkSize = CASES_PER_JOB;

        // Defensive fallback for pathological volumes: shrink the chunk so the
        // number of jobs still fits in the remaining queueable capacity.
        if (size > chunkSize * remainingJobs) {
            chunkSize = Math.max(1, (size + remainingJobs - 1) / remainingJobs);
        }

        for (Integer start = 0; start < size; start += chunkSize) {
            System.enqueueJob(new CaseSurveyJob(buildChunk(caseIds, start, chunkSize)));
        }
    }

    /**
     * Copies caseIds[startIndex .. startIndex + chunkSize) into a new list.
     * Apex List has no subList(), so the chunk is built with an explicit loop.
     */
    @TestVisible
    private static List<Id> buildChunk(List<Id> caseIds, Integer startIndex, Integer chunkSize) {
        List<Id> chunk = new List<Id>();
        Integer end = Math.min(startIndex + chunkSize, caseIds.size());
        for (Integer i = startIndex; i < end; i++) {
            chunk.add(caseIds[i]);
        }
        return chunk;
    }

    /**
     * Creates one CSAT survey Task per closed case that has a contact.
     * Uses a partial-success insert so a single failure is logged and does
     * not prevent tasks for the other cases in this chunk.
     */
    public void execute(QueueableContext context) {
        // Re-query at execution time: the trigger records may be stale, and
        // filtering on ContactId here cleanly implements "no contact -> no task".
        List<Case> cases = [
            SELECT Id, CaseNumber, ContactId
            FROM Case
            WHERE Id IN :caseIds
              AND ContactId != null
            WITH USER_MODE
        ];

        if (cases.isEmpty()) {
            return;
        }

        List<Task> tasks = new List<Task>();
        for (Case c : cases) {
            tasks.add(new Task(
                WhatId = c.Id,
                WhoId = c.ContactId,
                Subject = 'CSAT survey: ' + c.CaseNumber,
                ActivityDate = Date.today().addDays(2),
                Status = 'Not Started'
            ));
        }

        // Partial success: per-case isolation inside the chunk.
        Database.SaveResult[] results = Database.insert(tasks, false, AccessLevel.USER_MODE);

        for (Integer i = 0; i < results.size(); i++) {
            if (!results[i].isSuccess()) {
                for (Database.Error err : results[i].getErrors()) {
                    System.debug(
                        LoggingLevel.ERROR,
                        'CaseSurveyJob: failed to create CSAT task for case ' +
                        tasks[i].WhatId + ': ' + err.getStatusCode() + ' - ' + err.getMessage()
                    );
                }
                // In a production org, replace/augment this with durable error
                // logging (custom object, Platform Event, or partners' logger)
                // so failures are actionable rather than only in debug logs.
            }
        }
    }
}
