import { LightningElement, wire } from 'lwc';
import {
    MessageContext,
    publish,
    subscribe,
    unsubscribe,
    APPLICATION_SCOPE
} from 'lightning/messageService';
import ACCOUNT_SELECTED_CHANNEL from '@salesforce/messageChannel/Account_Selected__c';

export default class AccountDetailsPanel extends LightningElement {
    @wire(MessageContext)
    messageContext;

    subscription = null;
    selectedRecordId;

    connectedCallback() {
        this.subscribeToChannel();
    }

    disconnectedCallback() {
        this.unsubscribeFromChannel();
    }

    subscribeToChannel() {
        // Never hold more than one subscription at a time.
        if (this.subscription) {
            return;
        }
        // The publisher lives in the utility bar, which is outside the
        // component hierarchy of this app page, so APPLICATION_SCOPE is
        // required to receive its messages.
        this.subscription = subscribe(
            this.messageContext,
            ACCOUNT_SELECTED_CHANNEL,
            (message) => this.handleMessage(message),
            { scope: APPLICATION_SCOPE }
        );
    }

    unsubscribeFromChannel() {
        if (this.subscription) {
            unsubscribe(this.subscription);
            this.subscription = null;
        }
    }

    handleMessage(message) {
        if (message && message.recordId) {
            this.selectedRecordId = message.recordId;
        } else {
            this.selectedRecordId = null;
        }
    }

    handleClear() {
        // Publish a cleared selection on the same channel so that every
        // listening component (including this panel) clears its selection.
        publish(this.messageContext, ACCOUNT_SELECTED_CHANNEL, {
            recordId: null
        });
    }
}
