import { LightningElement } from 'lwc';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';
import register from '@salesforce/apex/RegistrationController.register';

const BLOCKED_EMAIL_DOMAINS = ['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com'];

export default class EventRegistrationForm extends LightningElement {
    fullName = '';
    email = '';
    company = '';

    handleChange(event) {
        const field = event.currentTarget.dataset.field;
        const value = event.detail.value;
        switch (field) {
            case 'fullName':
                this.fullName = value;
                break;
            case 'email':
                this.email = value;
                break;
            case 'company':
                this.company = value;
                break;
            default:
                break;
        }
    }

    handleRegister() {
        const emailInput = this.template.querySelector('[data-field="email"]');

        // Step 1: block personal email domains with a custom validity message.
        const emailDomain = this.email ? this.email.split('@').pop().toLowerCase() : '';
        if (BLOCKED_EMAIL_DOMAINS.includes(emailDomain)) {
            emailInput.setCustomValidity('Use your work email address.');
        } else {
            emailInput.setCustomValidity('');
        }

        // Step 2: report validity on every input so all messages show at once.
        const inputs = this.template.querySelectorAll('lightning-input');
        let allValid = true;
        inputs.forEach((input) => {
            const isValid = input.reportValidity();
            if (!isValid) {
                allValid = false;
            }
        });

        // Step 3: stop if anything is invalid.
        if (!allValid) {
            return;
        }

        Promise.resolve(
            register({ fullName: this.fullName, email: this.email, company: this.company })
        )
            .then(() => {
                this.dispatchEvent(
                    new ShowToastEvent({
                        title: 'Registered',
                        variant: 'success'
                    })
                );
            })
            .catch((error) => {
                const message =
                    error && error.body && error.body.message
                        ? error.body.message
                        : undefined;
                this.dispatchEvent(
                    new ShowToastEvent({
                        title: 'Registration failed',
                        message,
                        variant: 'error'
                    })
                );
            });
    }
}
