/**
 * @description Sets each Contact's current employer by creating or updating the
 * NPSP primary affiliation between the Contact and the given Organization Account.
 *
 * Uses the NPSP standard mechanism: by writing an Affiliation with
 * Status = 'Current' and Primary = true, the NPSP Affiliation trigger takes care of
 *   - populating Contact.npsp__Primary_Affiliation__c with the organization,
 *   - demoting the Contact's previous Current primary affiliation to
 *     Status = 'Former', Primary = false, EndDate = today,
 *   - leaving the Contact's household Account (AccountId) untouched.
 *
 * Limits: one SOQL query (existing affiliations between the given contacts and
 * organizations) and at most two DML statements (one update, one insert), so a
 * batch of 200 contacts is handled comfortably in a single call.
 */
public inherited sharing class EmployerService {

    private static final String STATUS_CURRENT = 'Current';

    // NPSP default contact-side role for an employment affiliation.
    private static final String ROLE_EMPLOYEE = 'Employee';

    /**
     * @description For each entry, makes employerByContactId the Contact's Current,
     *              primary NPSP affiliation and primary affiliation lookup.
     *              Contacts whose requested organization is already their Current,
     *              primary affiliation are left completely untouched (no duplicates,
     *              no unnecessary DML).
     * @param       employerByContactId Map of Contact Id -> Organization Account Id.
     *              Null or empty map, or entries with null Ids, are ignored.
     */
    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        // Nothing to do for a null or empty map.
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        // Defensive copy, dropping malformed entries, and de-duplicating org Ids for the query filter.
        Map<Id, Id> requested = new Map<Id, Id>();
        for (Id contactId : employerByContactId.keySet()) {
            Id orgId = employerByContactId.get(contactId);
            if (contactId != null && orgId != null) {
                requested.put(contactId, orgId);
            }
        }
        if (requested.isEmpty()) {
            return;
        }

        Set<Id> contactIds = requested.keySet();
        Set<Id> orgIds = new Set<Id>(requested.values());

        // Query 1 (of 1): only the affiliations that matter, i.e. between the requested
        // contacts and the requested organizations.
        Map<String, npe5__Affiliation__c> existingByKey = new Map<String, npe5__Affiliation__c>();
        for (npe5__Affiliation__c aff : [
            SELECT Id,
                   npe5__Contact__c,
                   npe5__Organization__c,
                   npe5__Status__c,
                   npe5__Primary__c,
                   npe5__StartDate__c
            FROM npe5__Affiliation__c
            WHERE npe5__Contact__c IN :contactIds
              AND npe5__Organization__c IN :orgIds
        ]) {
            String key = toKey(aff.npe5__Contact__c, aff.npe5__Organization__c);
            npe5__Affiliation__c held = existingByKey.get(key);
            // Keep a Current+Primary row if more than one affiliation exists for the pair,
            // so we correctly detect "already the primary employer".
            if (held == null || (aff.npe5__Status__c == STATUS_CURRENT && aff.npe5__Primary__c)) {
                existingByKey.put(key, aff);
            }
        }

        Date today = Date.today();
        List<npe5__Affiliation__c> affiliationsToUpdate = new List<npe5__Affiliation__c>();
        List<npe5__Affiliation__c> affiliationsToInsert = new List<npe5__Affiliation__c>();

        for (Id contactId : requested.keySet()) {
            Id orgId = requested.get(contactId);
            npe5__Affiliation__c existing = existingByKey.get(toKey(contactId, orgId));

            if (existing != null) {
                if (existing.npe5__Status__c == STATUS_CURRENT && existing.npe5__Primary__c) {
                    // The organization is already the Contact's Current primary
                    // affiliation: nothing changes, no duplicate is created.
                    continue;
                }
                // Reactivate the existing affiliation (e.g. it is Former, or Current
                // but not primary). NPSP handles demoting the previous primary.
                existing.npe5__Status__c = STATUS_CURRENT;
                existing.npe5__Primary__c = true;
                existing.npe5__EndDate__c = null;
                if (existing.npe5__StartDate__c == null) {
                    existing.npe5__StartDate__c = today;
                }
                affiliationsToUpdate.add(existing);
            } else {
                // New employment affiliation. NPSP maintains Contact.npsp__Primary_Affiliation__c
                // and demotes the previous Current primary affiliation to Former/non-primary
                // with EndDate = today. The Contact's household Account is not touched.
                affiliationsToInsert.add(new npe5__Affiliation__c(
                    npe5__Contact__c = contactId,
                    npe5__Organization__c = orgId,
                    npe5__Status__c = STATUS_CURRENT,
                    npe5__Primary__c = true,
                    npe5__StartDate__c = today,
                    npe5__Role__c = ROLE_EMPLOYEE
                ));
            }
        }

        // DML 1 and 2 (of 2): one update, one insert; each executed only if non-empty.
        // Run after all rows are collected so every operation is a single bulk DML.
        if (!affiliationsToUpdate.isEmpty()) {
            update affiliationsToUpdate;
        }
        if (!affiliationsToInsert.isEmpty()) {
            insert affiliationsToInsert;
        }
    }

    /**
     * @description Builds a stable map key for a (Contact, Organization) pair.
     * @param       contactId Contact Id.
     * @param       orgId     Organization Account Id.
     * @return      String key combining both Ids.
     */
    private static String toKey(Id contactId, Id orgId) {
        return String.valueOf(contactId) + '-' + String.valueOf(orgId);
    }
}
