/**
 * @description Service that records monthly giving sign-ups from the nonprofit's
 * donation form as Enhanced Recurring Donations (npe03__Recurring_Donation__c).
 *
 * Design notes:
 *  - Bulk-safe: the whole request list is validated up-front and inserted with a
 *    single DML statement. No SOQL is required (0 SOQL / 1 DML for any list size).
 *  - Open-ended vs fixed-length is driven by npsp__RecurringType__c
 *    ('Open' / 'Fixed') plus npe03__Open_Ended_Status__c and
 *    npe03__Installments__c.
 *  - The form's day "31" is stored using Enhanced Recurring Donations' native
 *    last-day-of-month option (npsp__Always_Use_Last_Day_Of_Month__c = true).
 *    Days 29 and 30 are stored as those exact days (months without a 29th/30th
 *    are skipped, which matches NPSP's installment schedule generation).
 *  - NPSP's own trigger/framework generates the installment Opportunities from
 *    these records; this service never creates Opportunities itself.
 */
public inherited sharing class RecurringGiftService {

    public class RecurringGiftException extends Exception {}

    /**
     * @description One monthly-giving sign-up coming from the donation form.
     */
    public class GiftRequest {
        public Id contactId;
        public Decimal amount;
        public Integer dayOfMonth;    // 1-31
        public Date startDate;
        public Integer installments;  // null or 0 = no end date
        public String paymentMethod;  // 'Credit Card', 'ACH' or 'Check'
    }

    private static final String INSTALLMENT_PERIOD_MONTHLY = 'Monthly';
    private static final String SCHEDULE_TYPE_MULTIPLY = 'Multiply by';
    private static final String RECURRING_TYPE_OPEN = 'Open';
    private static final String RECURRING_TYPE_FIXED = 'Fixed';
    private static final String OPEN_ENDED_STATUS_OPEN = 'Open';
    private static final String OPEN_ENDED_STATUS_FIXED = 'Fixed';
    private static final String STATUS_ACTIVE = 'Active';

    /**
     * @description Creates one Enhanced Recurring Donation per request.
     * @param requests The sign-ups to record. Null or empty returns an empty list.
     * @return The new Recurring Donation Ids, in request order.
     * @throws RecurringGiftService.RecurringGiftException if any request is
     *         invalid (null contact, null/non-positive amount, dayOfMonth
     *         outside 1-31, or null startDate). Thrown before any DML.
     */
    public static List<Id> createMonthlyGifts(List<GiftRequest> requests) {
        List<Id> recurringDonationIds = new List<Id>();

        // Null or empty list is a no-op that returns an empty list.
        if (requests == null || requests.isEmpty()) {
            return recurringDonationIds;
        }

        // Validate every request before any DML so the whole call is atomic
        // from the caller's perspective.
        validateRequests(requests);

        // Build all records, then insert once (1 DML statement total).
        List<npe03__Recurring_Donation__c> recurringDonations =
            new List<npe03__Recurring_Donation__c>();

        for (GiftRequest request : requests) {
            recurringDonations.add(buildRecurringDonation(request));
        }

        insert recurringDonations;

        for (npe03__Recurring_Donation__c recurringDonation : recurringDonations) {
            recurringDonationIds.add(recurringDonation.Id);
        }

        return recurringDonationIds;
    }

    /**
     * @description Validates all requests and throws a single exception listing
     *              every problem found. Runs before any DML.
     */
    private static void validateRequests(List<GiftRequest> requests) {
        List<String> errors = new List<String>();

        for (Integer i = 0; i < requests.size(); i++) {
            GiftRequest request = requests[i];
            String requestLabel = 'Request ' + (i + 1);

            if (request == null) {
                errors.add(requestLabel + ': request cannot be null.');
                continue;
            }
            if (request.contactId == null) {
                errors.add(requestLabel + ': contactId is required.');
            }
            if (request.amount == null || request.amount <= 0) {
                errors.add(requestLabel + ': amount must be a positive number.');
            }
            if (request.dayOfMonth == null || request.dayOfMonth < 1
                    || request.dayOfMonth > 31) {
                errors.add(requestLabel + ': dayOfMonth must be between 1 and 31.');
            }
            if (request.startDate == null) {
                errors.add(requestLabel + ': startDate is required.');
            }
        }

        if (!errors.isEmpty()) {
            throw new RecurringGiftException(
                'Invalid recurring gift request(s): ' + String.join(errors, ' '));
        }
    }

    /**
     * @description Builds one Enhanced Recurring Donation for a validated request.
     *              NPSP generates the installment Opportunities from this record;
     *              no Opportunities are created here.
     */
    private static npe03__Recurring_Donation__c buildRecurringDonation(
        GiftRequest request
    ) {
        Boolean openEnded = request.installments == null || request.installments == 0;

        npe03__Recurring_Donation__c recurringDonation =
            new npe03__Recurring_Donation__c(
                // Donor
                npe03__Contact__c = request.contactId,

                // Each installment is `amount`, once per month
                // ("Multiply by": per-installment amount x number of installments).
                npe03__Amount__c = request.amount,
                npe03__Schedule_Type__c = SCHEDULE_TYPE_MULTIPLY,
                npe03__Installment_Period__c = INSTALLMENT_PERIOD_MONTHLY,
                npsp__InstallmentFrequency__c = 1,

                // Monthly schedule on the requested day of month.
                // The form's "31" means "last day of the month", which Enhanced
                // Recurring Donations expresses with its own dedicated option;
                // 29 and 30 are stored as those days.
                npsp__Day_of_Month__c = request.dayOfMonth,
                npsp__Always_Use_Last_Day_Of_Month__c = (request.dayOfMonth == 31),
                npsp__StartDate__c = request.startDate,
                npe03__Date_Established__c = request.startDate,
                npe03__Next_Payment_Date__c =
                    firstPaymentDate(request.startDate, request.dayOfMonth),

                // Sign-ups start out Active with the form's payment method.
                npsp__Status__c = STATUS_ACTIVE,
                npsp__PaymentMethod__c = request.paymentMethod
            );

        if (openEnded) {
            // null or 0 installments = open-ended recurring donation.
            recurringDonation.npsp__RecurringType__c = RECURRING_TYPE_OPEN;
            recurringDonation.npe03__Open_Ended_Status__c = OPEN_ENDED_STATUS_OPEN;
            recurringDonation.npe03__Installments__c = null;
        } else {
            // Fixed-length recurring donation with the requested number of
            // planned installments; NPSP derives the end date.
            recurringDonation.npsp__RecurringType__c = RECURRING_TYPE_FIXED;
            recurringDonation.npe03__Open_Ended_Status__c = OPEN_ENDED_STATUS_FIXED;
            recurringDonation.npe03__Installments__c = request.installments;
        }

        return recurringDonation;
    }

    /**
     * @description First installment date on or after startDate.
     *  - dayOfMonth 31: last day of the month; startDate itself if it is a
     *    month's last day, otherwise the last day of startDate's month.
     *  - dayOfMonth 1-30: the first date on or after startDate whose day equals
     *    dayOfMonth, skipping months that do not contain that day (e.g. a
     *    day-of-month of 29 starting in a non-leap February first falls on
     *    March 29).
     */
    private static Date firstPaymentDate(Date startDate, Integer dayOfMonth) {
        if (dayOfMonth == 31) {
            if (startDate.day() == daysInMonthOf(startDate)) {
                return startDate;
            }
            return lastDayOfMonth(startDate);
        }

        Integer monthOffset = 0;
        // At most 12 iterations: any day 1-30 occurs within the next 12 months.
        while (monthOffset < 12) {
            Date candidateMonthStart = startDate.toStartOfMonth().addMonths(monthOffset);
            Integer monthLength = daysInMonthOf(candidateMonthStart);
            if (monthLength >= dayOfMonth) {
                Date candidate = candidateMonthStart.addDays(dayOfMonth - 1);
                if (candidate >= startDate) {
                    return candidate;
                }
            }
            monthOffset++;
        }
        // Unreachable for dayOfMonth 1-30; kept as a safe fallback.
        return startDate;
    }

    /**
     * @description The number of days in the month containing the given date,
     *              using the static Date.daysInMonth(year, month) API.
     */
    private static Integer daysInMonthOf(Date theDate) {
        return Date.daysInMonth(theDate.year(), theDate.month());
    }

    /**
     * @description The last calendar day of the month containing the given date.
     */
    private static Date lastDayOfMonth(Date theDate) {
        return theDate.toStartOfMonth().addMonths(1).addDays(-1);
    }
}
