/**
 * @description Service for managing NPSP partial soft credits for peer-to-peer
 * fundraising integrations.
 *
 * For each SoftCreditRequest the specified contact ends up with:
 *   - Exactly one OpportunityContactRole on the opportunity whose Role equals the
 *     requested role (an existing contact role, e.g. NPSP's "Household Member",
 *     is repurposed rather than duplicated).
 *   - Exactly one npsp__Partial_Soft_Credit__c linked to that contact role, with
 *     the requested amount and role name (an existing partial soft credit for the
 *     same opportunity/contact pair is updated, not duplicated).
 *
 * All validation happens up front: if any request is invalid, a SoftCreditException
 * is thrown and no DML is performed.
 *
 * Governor limits: a call with 200 requests uses at most 3 SOQL queries and
 * 4 DML statements.
 */
public inherited sharing class SoftCreditService {

    public class SoftCreditException extends Exception {}

    /**
     * @description One requested partial soft credit.
     */
    public class SoftCreditRequest {
        public Id opportunityId;
        public Id contactId;
        public Decimal amount;
        public String role;

        public SoftCreditRequest() {}

        public SoftCreditRequest(Id opportunityId, Id contactId, Decimal amount, String role) {
            this.opportunityId = opportunityId;
            this.contactId = contactId;
            this.amount = amount;
            this.role = role;
        }
    }

    private static final String KEY_SEP = '-';

    /**
     * @description Adds or updates partial soft credits for the given requests.
     * @param requests The requested partial soft credits. Null or empty input does nothing.
     *                 The same opportunity/contact pair must not appear more than once.
     * @throws SoftCreditService.SoftCreditException if any request is invalid. Nothing is
     *         changed when any request is invalid.
     */
    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {
        // Nothing to do for null or empty input.
        if (requests == null || requests.isEmpty()) {
            return;
        }

        // ------------------------------------------------------------------
        // 1. Gather the ids we need (SOQL #1: opportunities, #2: contact roles,
        //    #3: existing partial soft credits).
        // ------------------------------------------------------------------
        Set<Id> opportunityIds = new Set<Id>();
        Set<Id> contactIds = new Set<Id>();
        for (SoftCreditRequest req : requests) {
            if (req.opportunityId != null) {
                opportunityIds.add(req.opportunityId);
            }
            if (req.contactId != null) {
                contactIds.add(req.contactId);
            }
        }

        // SOQL #1 - opportunities to validate against.
        Map<Id, Opportunity> opportunities = new Map<Id, Opportunity>(
            [SELECT Id, Amount, npsp__Primary_Contact__c
             FROM Opportunity
             WHERE Id IN :opportunityIds]
        );

        // SOQL #2 - existing contact roles for the requested contact/opportunity pairs.
        // Key: opportunityId + '-' + contactId
        Map<String, List<OpportunityContactRole>> existingRolesByKey =
            new Map<String, List<OpportunityContactRole>>();
        for (OpportunityContactRole ocr : [
            SELECT Id, OpportunityId, ContactId, Role
            FROM OpportunityContactRole
            WHERE OpportunityId IN :opportunityIds
              AND ContactId IN :contactIds
        ]) {
            String key = ocr.OpportunityId + KEY_SEP + ocr.ContactId;
            if (!existingRolesByKey.containsKey(key)) {
                existingRolesByKey.put(key, new List<OpportunityContactRole>());
            }
            existingRolesByKey.get(key).add(ocr);
        }

        // SOQL #3 - existing partial soft credits for the requested pairs.
        // Key: opportunityId + '-' + contactId. Duplicates beyond the first are
        // collected for cleanup.
        Map<String, npsp__Partial_Soft_Credit__c> existingPscByKey =
            new Map<String, npsp__Partial_Soft_Credit__c>();
        List<npsp__Partial_Soft_Credit__c> duplicatePscs =
            new List<npsp__Partial_Soft_Credit__c>();
        for (npsp__Partial_Soft_Credit__c psc : [
            SELECT Id, npsp__Opportunity__c, npsp__Contact__c, npsp__Amount__c,
                   npsp__Role_Name__c, npsp__Contact_Role_ID__c
            FROM npsp__Partial_Soft_Credit__c
            WHERE npsp__Opportunity__c IN :opportunityIds
              AND npsp__Contact__c IN :contactIds
        ]) {
            String key = psc.npsp__Opportunity__c + KEY_SEP + psc.npsp__Contact__c;
            if (existingPscByKey.containsKey(key)) {
                duplicatePscs.add(psc);
            } else {
                existingPscByKey.put(key, psc);
            }
        }

        // ------------------------------------------------------------------
        // 2. Validate every request before any DML. Any failure aborts the
        //    whole call without changing anything.
        // ------------------------------------------------------------------
        for (SoftCreditRequest req : requests) {
            Opportunity opp = opportunities.get(req.opportunityId);
            if (opp == null) {
                throw new SoftCreditException(
                    'Opportunity not found for request: ' + req.opportunityId);
            }
            if (opp.npsp__Primary_Contact__c == req.contactId) {
                throw new SoftCreditException(
                    'Contact ' + req.contactId +
                    ' is the primary contact of opportunity ' + req.opportunityId +
                    ' and cannot receive a partial soft credit.');
            }
            if (req.amount == null) {
                throw new SoftCreditException(
                    'Partial soft credit amount cannot be null for contact ' +
                    req.contactId + ' on opportunity ' + req.opportunityId + '.');
            }
            if (req.amount <= 0) {
                throw new SoftCreditException(
                    'Partial soft credit amount must be positive for contact ' +
                    req.contactId + ' on opportunity ' + req.opportunityId + '.');
            }
            // An opportunity without an amount cannot be exceeded.
            if (opp.Amount != null && req.amount > opp.Amount) {
                throw new SoftCreditException(
                    'Partial soft credit amount ' + req.amount +
                    ' exceeds the opportunity amount ' + opp.Amount +
                    ' for contact ' + req.contactId +
                    ' on opportunity ' + req.opportunityId + '.');
            }
        }

        // ------------------------------------------------------------------
        // 3. Plan the contact role changes. End state per request: exactly one
        //    OpportunityContactRole for the contact on the opportunity, with
        //    Role equal to the requested role.
        // ------------------------------------------------------------------
        List<OpportunityContactRole> rolesToUpdate = new List<OpportunityContactRole>();
        List<OpportunityContactRole> rolesToInsert = new List<OpportunityContactRole>();
        List<OpportunityContactRole> rolesToDelete = new List<OpportunityContactRole>();
        // Key: opportunityId + '-' + contactId -> the role the soft credit will link to.
        Map<String, OpportunityContactRole> keeperRoleByKey =
            new Map<String, OpportunityContactRole>();

        for (SoftCreditRequest req : requests) {
            String key = req.opportunityId + KEY_SEP + req.contactId;
            List<OpportunityContactRole> existingRoles = existingRolesByKey.get(key);
            OpportunityContactRole keeper;

            if (existingRoles == null || existingRoles.isEmpty()) {
                // No contact role yet - create one with the requested role.
                keeper = new OpportunityContactRole(
                    OpportunityId = req.opportunityId,
                    ContactId = req.contactId,
                    Role = req.role
                );
                rolesToInsert.add(keeper);
            } else {
                // Prefer a role that already has the requested name; otherwise
                // repurpose the first existing role (e.g. NPSP's Household Member).
                for (OpportunityContactRole ocr : existingRoles) {
                    if (ocr.Role == req.role) {
                        keeper = ocr;
                        break;
                    }
                }
                if (keeper == null) {
                    keeper = existingRoles[0];
                }
                if (keeper.Role != req.role) {
                    keeper.Role = req.role;
                    rolesToUpdate.add(keeper);
                }
                // Enforce "exactly one" contact role for this contact/opportunity.
                for (OpportunityContactRole ocr : existingRoles) {
                    if (ocr.Id != keeper.Id) {
                        rolesToDelete.add(ocr);
                    }
                }
            }
            keeperRoleByKey.put(key, keeper);
        }

        // ------------------------------------------------------------------
        // 4. DML #1 and #2: contact roles. Inserted roles need their Ids before
        //    the partial soft credits can be linked.
        // ------------------------------------------------------------------
        if (!rolesToUpdate.isEmpty()) {
            update rolesToUpdate;
        }
        if (!rolesToInsert.isEmpty()) {
            insert rolesToInsert;
        }

        // ------------------------------------------------------------------
        // 5. Build the partial soft credits: insert new ones, update existing
        //    ones (same opportunity/contact pair) with the new amount and role.
        //    npsp__Contact_Name__c is not written here - it is not a writeable
        //    field in this org; the contact is identified via npsp__Contact__c.
        // ------------------------------------------------------------------
        List<npsp__Partial_Soft_Credit__c> partialSoftCredits =
            new List<npsp__Partial_Soft_Credit__c>();

        for (SoftCreditRequest req : requests) {
            String key = req.opportunityId + KEY_SEP + req.contactId;
            OpportunityContactRole keeperRole = keeperRoleByKey.get(key);

            npsp__Partial_Soft_Credit__c psc = existingPscByKey.get(key);
            if (psc == null) {
                psc = new npsp__Partial_Soft_Credit__c();
            }
            psc.npsp__Opportunity__c = req.opportunityId;
            psc.npsp__Contact__c = req.contactId;
            psc.npsp__Amount__c = req.amount;
            psc.npsp__Role_Name__c = req.role;
            psc.npsp__Contact_Role_ID__c = keeperRole.Id;
            partialSoftCredits.add(psc);
        }

        // DML #3: records with an Id are updated, records without one are inserted.
        if (!partialSoftCredits.isEmpty()) {
            upsert partialSoftCredits;
        }

        // DML #4: clean up surplus contact roles and duplicate partial soft
        // credits so each contact/opportunity pair ends up with exactly one of each.
        List<sObject> toDelete = new List<sObject>();
        toDelete.addAll(rolesToDelete);
        toDelete.addAll(duplicatePscs);
        if (!toDelete.isEmpty()) {
            delete toDelete;
        }
    }
}
