/**
 * @description Service for recording gifts (donations) that have already been received,
 * in an org running the Nonprofit Success Pack (NPSP) with the Household Account
 * model and NPSP Payments enabled.
 *
 * The gift is credited the way NPSP expects:
 *  - The Opportunity belongs to the Contact's Household Account.
 *  - The donor Contact is the Opportunity's Primary Contact and holds the 'Donor'
 *    OpportunityContactRole.
 *  - Every other member of the household holds the 'Household Member' role, and no
 *    Contact ends up with more than one contact role on the Opportunity.
 *  - Exactly one NPSP Payment exists: paid, for the full amount, dated the gift date.
 *
 * The reconciliations below are written to be safe whether or not NPSP's own
 * automations (primary-contact role creation, household-member role creation and
 * automatic payment creation on Closed Won opportunities) have already fired
 * synchronously during the Opportunity insert: existing records are corrected
 * instead of blindly duplicated.
 */
public class GiftService {

    private static final String STAGE_CLOSED_WON = 'Closed Won';
    private static final String DONOR_ROLE = 'Donor';
    private static final String HOUSEHOLD_MEMBER_ROLE = 'Household Member';

    /**
     * @description Records a gift that has already been received.
     * @param contactId Id of the donor Contact. Must exist and belong to a Household Account.
     * @param amount    Amount of the gift. Must be non-null, greater than zero.
     * @param giftDate  Date the gift was received/closed and the payment was made.
     * @return Id of the newly created Opportunity.
     * @throws IllegalArgumentException if the Contact does not exist, has no Household
     *                                  Account, or if amount is null, zero or negative
     *                                  (or giftDate is null).
     */
    public static Id recordGift(Id contactId, Decimal amount, Date giftDate) {
        // ----- Input validation ----------------------------------------------
        if (contactId == null) {
            throw new IllegalArgumentException('Contact Id must not be null.');
        }
        if (amount == null || amount <= 0) {
            throw new IllegalArgumentException('Amount must be a positive, non-zero value.');
        }
        if (giftDate == null) {
            throw new IllegalArgumentException('Gift date must not be null.');
        }

        // ----- Donor lookup ----------------------------------------------------
        List<Contact> contacts = [
            SELECT Id, AccountId, FirstName, LastName
            FROM Contact
            WHERE Id = :contactId
            LIMIT 1
        ];
        if (contacts.isEmpty()) {
            throw new IllegalArgumentException('Contact does not exist: ' + contactId);
        }
        Contact donor = contacts[0];
        if (donor.AccountId == null) {
            throw new IllegalArgumentException(
                'Contact ' + contactId + ' is not associated with a Household Account.');
        }

        // All other Contacts on the Household Account are household members.
        List<Contact> householdMembers = [
            SELECT Id
            FROM Contact
            WHERE AccountId = :donor.AccountId
              AND Id != :donor.Id
        ];

        // ----- Opportunity -----------------------------------------------------
        Opportunity opp = new Opportunity(
            Name = buildOpportunityName(donor, giftDate),
            AccountId = donor.AccountId,
            ContactId = donor.Id,
            npsp__Primary_Contact__c = donor.Id,
            Amount = amount,
            CloseDate = giftDate,
            StageName = STAGE_CLOSED_WON
        );
        insert opp;

        // ----- Contact roles and payment ---------------------------------------
        // These run after the Opportunity insert so they can see and correct any
        // records NPSP's own triggers have already created (e.g. the automatic
        // payment on Closed Won or default contact roles), guaranteeing exactly
        // one role per Contact and exactly one payment.
        reconcileContactRoles(opp.Id, donor.Id, householdMembers);
        reconcilePayment(opp.Id, amount, giftDate);

        return opp.Id;
    }

    /**
     * @description Builds the Opportunity Name: '<FirstName> <LastName> Donation <yyyy-MM-dd>'.
     */
    private static String buildOpportunityName(Contact donor, Date giftDate) {
        String firstNamePart = String.isBlank(donor.FirstName) ? '' : donor.FirstName.trim() + ' ';
        return firstNamePart + donor.LastName + ' Donation ' + formatDate(giftDate);
    }

    /**
     * @description Formats a Date as yyyy-MM-dd (zero-padded month and day).
     */
    private static String formatDate(Date d) {
        return d.year()
            + '-' + String.valueOf(d.month()).leftPad(2, '0')
            + '-' + String.valueOf(d.day()).leftPad(2, '0');
    }

    /**
     * @description Ensures the Opportunity has exactly the expected contact roles:
     *              the donor with role 'Donor' (and IsPrimary = true), and every other
     *              household member with role 'Household Member'. Existing roles created
     *              by NPSP are updated rather than duplicated; any duplicate role for the
     *              same Contact, or a role belonging to a Contact outside the household,
     *              is removed.
     */
    private static void reconcileContactRoles(
        Id opportunityId, Id donorId, List<Contact> householdMembers) {

        // Desired role per Contact.
        Map<Id, String> desiredRoles = new Map<Id, String>();
        desiredRoles.put(donorId, DONOR_ROLE);
        for (Contact member : householdMembers) {
            if (member.Id != donorId) {
                desiredRoles.put(member.Id, HOUSEHOLD_MEMBER_ROLE);
            }
        }

        List<OpportunityContactRole> existing = [
            SELECT Id, ContactId, Role, IsPrimary
            FROM OpportunityContactRole
            WHERE OpportunityId = :opportunityId
        ];

        Map<Id, OpportunityContactRole> roleByContact = new Map<Id, OpportunityContactRole>();
        List<OpportunityContactRole> toDelete = new List<OpportunityContactRole>();
        for (OpportunityContactRole ocr : existing) {
            if (!desiredRoles.containsKey(ocr.ContactId)
                    || roleByContact.containsKey(ocr.ContactId)) {
                // Role for a Contact outside the household, or a duplicate role
                // for the same Contact: remove it so no Contact ends up with more
                // than one role on the gift.
                toDelete.add(ocr);
            } else {
                roleByContact.put(ocr.ContactId, ocr);
            }
        }

        List<OpportunityContactRole> toInsert = new List<OpportunityContactRole>();
        List<OpportunityContactRole> toUpdate = new List<OpportunityContactRole>();
        for (Id contactId : desiredRoles.keySet()) {
            String desiredRole = desiredRoles.get(contactId);
            Boolean shouldBePrimary = (contactId == donorId);
            OpportunityContactRole ocr = roleByContact.get(contactId);
            if (ocr == null) {
                toInsert.add(new OpportunityContactRole(
                    OpportunityId = opportunityId,
                    ContactId = contactId,
                    Role = desiredRole,
                    IsPrimary = shouldBePrimary
                ));
            } else if (ocr.Role != desiredRole || ocr.IsPrimary != shouldBePrimary) {
                ocr.Role = desiredRole;
                ocr.IsPrimary = shouldBePrimary;
                toUpdate.add(ocr);
            }
        }

        if (!toDelete.isEmpty()) {
            delete toDelete;
        }
        if (!toUpdate.isEmpty()) {
            update toUpdate;
        }
        if (!toInsert.isEmpty()) {
            insert toInsert;
        }
    }

    /**
     * @description Ensures the Opportunity has exactly one NPSP payment: paid, for the
     *              full amount, with both the scheduled and payment dates set to the
     *              gift date. If NPSP's automatic payment creation already produced a
     *              payment, that payment is updated instead of a second one inserted;
     *              any extra duplicate payments are removed.
     */
    private static void reconcilePayment(Id opportunityId, Decimal amount, Date giftDate) {
        List<npe01__OppPayment__c> payments = [
            SELECT Id, npe01__Payment_Amount__c, npe01__Payment_Date__c,
                   npe01__Scheduled_Date__c, npe01__Paid__c
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :opportunityId
            ORDER BY CreatedDate
        ];

        if (payments.isEmpty()) {
            npe01__OppPayment__c payment = new npe01__OppPayment__c(
                npe01__Opportunity__c = opportunityId
            );
            applyPaymentFields(payment, amount, giftDate);
            insert payment;
        } else {
            npe01__OppPayment__c payment = payments[0];
            applyPaymentFields(payment, amount, giftDate);
            update payment;

            if (payments.size() > 1) {
                // Remove any duplicate payments NPSP (or prior automation) created.
                List<npe01__OppPayment__c> toDelete = new List<npe01__OppPayment__c>();
                for (Integer i = 1; i < payments.size(); i++) {
                    toDelete.add(payments[i]);
                }
                delete toDelete;
            }
        }
    }

    /**
     * @description Applies the required payment field values.
     */
    private static void applyPaymentFields(
        npe01__OppPayment__c payment, Decimal amount, Date giftDate) {
        payment.npe01__Payment_Amount__c = amount;
        payment.npe01__Payment_Date__c = giftDate;
        payment.npe01__Scheduled_Date__c = giftDate;
        payment.npe01__Paid__c = true;
    }
}
