/**
 * @description  NPSP Table-Driven Trigger Management (TDTM) handler that creates a
 *               follow-up "Major gift thank-you call" Task when an Opportunity
 *               becomes a Closed Won major gift (Amount >= 5000).
 *
 *               Registration (done by the admin under NPSP Settings > Trigger
 *               Configuration, stored as a Trigger Handler custom-object record):
 *                 Class         : OPP_MajorGiftFollowUp_TDTM
 *                 Object        : Opportunity
 *                 Trigger Action: AfterInsert;AfterUpdate
 *                 Load Order    : 5
 *                 Asynchronous  : false
 *
 *               Lifecycle / safety notes:
 *               - No Apex trigger is needed (or allowed): the NPSP TDTM dispatcher
 *                 (npsp.TDTM_TriggerHandler) invokes run() for this class based on
 *                 the Trigger Handler record. When the admin deactivates that
 *                 record, the dispatcher simply stops calling this handler, so the
 *                 "switch off" behaviour is provided entirely by NPSP.
 *               - A task is created only on the transition into the qualifying
 *                 state ("Closed Won" AND Amount >= 5000). Editing a gift that
 *                 already qualified does not create another task.
 *               - Fully bulkified: 200 opportunities cost 1 SOQL query and 1 DML
 *                 statement (a single insert of up to 200 Tasks performed inside
 *                 run()).
 *               - Declared `global` so the managed-package dispatcher can
 *                 instantiate and dispatch the override.
 */
global with sharing class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {

    private static final String WON_STAGE = 'Closed Won';
    private static final Decimal QUALIFYING_AMOUNT = 5000;
    private static final String TASK_SUBJECT = 'Major gift thank-you call';
    private static final Integer FOLLOW_UP_DAYS = 3;

    /**
     * @description TDTM entrypoint. Called by the NPSP dispatcher only for the
     *              trigger actions configured on the Trigger Handler record
     *              (AfterInsert and AfterUpdate here).
     * @param  newlist       the incoming (new) versions of the records
     * @param  oldlist       the previous versions (null on insert)
     * @param  triggerAction the action being dispatched
     * @param  objResult     describe of the object the dispatcher is firing on
     * @return the (empty) DmlWrapper; all DML for this handler is performed
     *         directly inside run() as its single DML statement
     */
    global override npsp.TDTM_Runnable.DmlWrapper run(
        List<SObject> newlist,
        List<SObject> oldlist,
        npsp.TDTM_Runnable.Action triggerAction,
        Schema.DescribeSObjectResult objResult
    ) {
        npsp.TDTM_Runnable.DmlWrapper wrapper = new npsp.TDTM_Runnable.DmlWrapper();

        // Defensive guard: only the actions this handler is registered for.
        // (NPSP normally enforces this via the Trigger Handler record.)
        if (newlist == null
                || (triggerAction != npsp.TDTM_Runnable.Action.AfterInsert
                    && triggerAction != npsp.TDTM_Runnable.Action.AfterUpdate)) {
            return wrapper;
        }

        Boolean isInsert = (triggerAction == npsp.TDTM_Runnable.Action.AfterInsert);

        // Index the old records once for O(1) lookups.
        Map<Id, Opportunity> oldById = new Map<Id, Opportunity>();
        if (oldlist != null) {
            for (SObject oldRecord : oldlist) {
                oldById.put(oldRecord.Id, (Opportunity) oldRecord);
            }
        }

        // Pass 1 (no SOQL, no DML): determine which opportunities have *just*
        // become qualifying. An opportunity qualifies when StageName = 'Closed Won'
        // and Amount >= 5000. On update we only fire when it was NOT already
        // both of those before, so editing an already-qualified gift never
        // produces a second task.
        Set<Id> newlyQualifiedIds = new Set<Id>();
        for (SObject newRecord : newlist) {
            Opportunity opp = (Opportunity) newRecord;
            if (!isQualified(opp)) {
                continue;
            }
            if (!isInsert) {
                Opportunity oldOpp = oldById.get(opp.Id);
                if (oldOpp != null && isQualified(oldOpp)) {
                    // Already qualified before this update: skip.
                    continue;
                }
            }
            newlyQualifiedIds.add(opp.Id);
        }

        if (newlyQualifiedIds.isEmpty()) {
            return wrapper;
        }

        // Pass 2 (the handler's single SOQL query): re-query the newly qualified
        // opportunities so every field we need is guaranteed present, regardless
        // of how the triggering DML was constructed (API, Data Loader, inline
        // record, etc. — trigger context records may not carry unmodified fields).
        List<Opportunity> qualifyingOpps = [
            SELECT Id, OwnerId, CloseDate, npsp__Primary_Contact__c
            FROM Opportunity
            WHERE Id IN :newlyQualifiedIds
        ];

        // Build one Task per qualifying opportunity — 1 insert statement for the
        // whole batch (max 200 records in a trigger chunk). If this handler is
        // deactivated via its Trigger Handler record, the dispatcher never calls
        // run() and nothing is inserted.
        List<Task> tasks = new List<Task>();
        for (Opportunity opp : qualifyingOpps) {
            tasks.add(buildTask(opp));
        }

        if (!tasks.isEmpty()) {
            insert tasks;
        }
        return wrapper;
    }

    /**
     * @description True when the opportunity is Closed Won with Amount >= 5000.
     */
    private Boolean isQualified(Opportunity opp) {
        return opp.StageName == WON_STAGE
            && opp.Amount != null
            && opp.Amount >= QUALIFYING_AMOUNT;
    }

    /**
     * @description Builds the follow-up Task for one qualifying opportunity.
     *              WhoId is left null when the opportunity has no primary contact.
     *              ActivityDate is the CloseDate + 3 days (omitted if CloseDate
     *              is unexpectedly null, so the task is still created).
     */
    private Task buildTask(Opportunity opp) {
        Task task = new Task(
            Subject   = TASK_SUBJECT,
            Priority  = 'High',
            Status    = 'Not Started',
            WhatId    = opp.Id,
            OwnerId   = opp.OwnerId
        );
        if (opp.npsp__Primary_Contact__c != null) {
            task.WhoId = opp.npsp__Primary_Contact__c;
        }
        if (opp.CloseDate != null) {
            task.ActivityDate = opp.CloseDate.addDays(FOLLOW_UP_DAYS);
        }
        return task;
    }
}
