/**
 * RecordAccessService
 *
 * Returns the subset of given record IDs that the running user can edit,
 * as reported by the UserRecordAccess object (HasEditAccess).
 *
 * Design notes:
 *  - UserRecordAccess takes object permissions, ownership, sharing rules, the
 *    role hierarchy, View All / Modify All data permissions, parent records
 *    (master-detail / lookup sharing) etc. into account, so it is the single
 *    source of truth for "can this user edit this record?".
 *  - A record the user has no access to at all simply does not appear in the
 *    UserRecordAccess result, so it is treated as "not editable" (fail closed).
 *  - Input may be null/empty (returns empty set, never null) and may contain
 *    IDs of many different objects; UserRecordAccess is polymorphic, so a
 *    single query per chunk of mixed-object IDs works fine.
 *  - The RecordId filter on UserRecordAccess is chunked so we stay well inside
 *    governor limits: 2,000 IDs = 10 SOQL queries (budget: 20), regardless of
 *    what else runs in the same transaction.
 *  - Nulls and duplicates in the input are filtered out; the returned set is a
 *    strict subset of the input (and only real records with edit access).
 */
public with sharing class RecordAccessService {

    /**
     * Number of record IDs bound per UserRecordAccess query.
     * 200 keeps each query cheap and bounds the worst case at 10 queries
     * for the maximum 2,000-ID call, leaving headroom inside the 20-query
     * limit when the method runs mid-transaction.
     * Visible to tests so chunking can be exercised explicitly.
     */
    @TestVisible
    private static final Integer CHUNK_SIZE = 200;

    /**
     * Returns the subset of recordIds the running user can edit.
     *
     * @param recordIds up to 2,000 record IDs, possibly null/empty and possibly
     *                  spanning multiple objects
     * @return the IDs that have HasEditAccess = true for the running user;
     *         never null; empty set for null/empty/no-access input
     */
    public static Set<Id> editableIds(Set<Id> recordIds) {
        Set<Id> result = new Set<Id>();

        // Null or empty input -> empty set (never null).
        if (recordIds == null || recordIds.isEmpty()) {
            return result;
        }

        // De-duplicate and drop nulls so we never bind them into the query.
        Set<Id> candidates = new Set<Id>();
        for (Id recordId : recordIds) {
            if (recordId != null) {
                candidates.add(recordId);
            }
        }
        if (candidates.isEmpty()) {
            return result;
        }

        // Stable ordering for deterministic chunking (also makes the query
        // count predictable: ceil(candidates.size() / CHUNK_SIZE) queries).
        List<Id> ordered = new List<Id>(candidates);

        // Manual chunking (Apex List has no subList method): build each chunk
        // by index range, then query UserRecordAccess for that chunk.
        for (Integer start = 0; start < ordered.size(); start += CHUNK_SIZE) {
            Integer end = Math.min(start + CHUNK_SIZE, ordered.size());
            List<Id> chunk = new List<Id>();
            for (Integer i = start; i < end; i++) {
                chunk.add(ordered[i]);
            }

            // UserRecordAccess only returns a row for a record the user has at
            // least some access to; records with no access are absent, which
            // correctly resolves to "not editable". Filtering on the current
            // user's Id plus the RecordId chunk is the supported pattern and
            // works across mixed object types in one query.
            for (UserRecordAccess access : [
                SELECT RecordId, HasEditAccess
                FROM UserRecordAccess
                WHERE UserId = :UserInfo.getUserId()
                  AND RecordId IN :chunk
            ]) {
                if (access.HasEditAccess == true) {
                    result.add(access.RecordId);
                }
            }
        }

        return result;
    }
}
