```apex
/**
 * TAF action registered for the Opportunity sObject_Trigger_Setting__mdt record via the
 * Trigger_Action__mdt records TA_Opportunity_CollectForErpSync_AI (after insert) and
 * TA_Opportunity_CollectForErpSync_AU (after update).
 *
 * It collects, for the current DML operation, the Ids of every opportunity that must be
 * pushed to the ERP:
 *   - after insert : every record of the operation;
 *   - after update : only the records whose StageName changed.
 *
 * The Ids are accumulated in a transaction-scoped static set so that all trigger chunks of
 * a single DML operation are captured (e.g. one insert of 250 opportunities fires the
 * trigger in a 200 + 50 chunk split, yet all 250 Ids end up in this set, because both
 * chunks run inside the same transaction and share this static state).
 *
 * This class performs no DML and no SOQL: it is bulk-safe and recursion-safe. The framework
 * calls every registered DML finalizer at the end of each DML operation it handles;
 * OpportunityErpSyncFinalizer then drains this set and enqueues exactly one
 * OpportunityErpSyncJob when (and only when) Ids were collected for that operation, which
 * also keeps two separate DML statements in the same transaction as two separate jobs.
 */
public inherited sharing class TA_Opportunity_CollectForErpSync implements TriggerAction.AfterInsert, TriggerAction.AfterUpdate {

    /**
     * Ids of opportunities of the current DML operation that need to be synced to the ERP.
     * Drained (and cleared) by OpportunityErpSyncFinalizer at the end of the DML operation.
     */
    @TestVisible
    private static Set<Id> opportunityIdsToSync = new Set<Id>();

    /**
     * After insert: every opportunity of the operation must be pushed to the ERP.
     */
    public void afterInsert(List<SObject> triggerNew) {
        List<Id> ids = new List<Id>();
        for (SObject record : triggerNew) {
            ids.add(record.Id);
        }
        this.collect(ids);
    }

    /**
     * After update: only the opportunities whose StageName changed must be pushed to the ERP.
     */
    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        List<Id> ids = new List<Id>();
        for (Integer i = 0; i < triggerNew.size(); i++) {
            if (triggerNew[i].get(Schema.Opportunity.StageName) != triggerOld[i].get(Schema.Opportunity.StageName)) {
                ids.add(triggerNew[i].Id);
            }
        }
        this.collect(ids);
    }

    /**
     * Accumulates the given Ids into the transaction-scoped set. Using addAll keeps the set
     * de-duplicated across trigger chunks of the same DML operation.
     */
    private void collect(List<Id> ids) {
        if (!ids.isEmpty()) {
            opportunityIdsToSync.addAll(ids);
        }
    }

    /**
     * Returns the Ids collected since the previous call and resets the accumulator.
     * Invoked once per DML operation by OpportunityErpSyncFinalizer, which guarantees the
     * "one job per DML operation, carrying exactly the Ids of that operation" rule.
     */
    public static Set<Id> retrieveAndClear() {
        Set<Id> ids = new Set<Id>(opportunityIdsToSync);
        opportunityIdsToSync.clear();
        return ids;
    }
}
