/**
 * TAF DML finalizer, registered via the DML_Finalizer__mdt record
 * OpportunityErpSyncFinalizer (Order__c 10).
 *
 * The framework invokes every registered DML finalizer at the end of EVERY DML operation it
 * handles, regardless of the sObject involved. Therefore this class must be a no-op whenever
 * the DML operation that just completed did not collect any opportunity for ERP sync (for
 * example DML on other objects, or Opportunity updates that did not change StageName).
 *
 * For each DML operation it drains the Ids collected by TA_Opportunity_CollectForErpSync and
 * enqueues exactly one OpportunityErpSyncJob carrying those Ids; it enqueues nothing when the
 * drained set is empty. Enqueuing a Queueable is not DML, so it is allowed from a finalizer;
 * this class must never perform DML of its own.
 */
public inherited sharing class OpportunityErpSyncFinalizer implements TriggerAction.DmlFinalizer {

    /**
     * Called by the framework at the end of each DML operation it handles.
     */
    public void execute(FinalizerHandler.Context context) {
        Set<Id> opportunityIds = TA_Opportunity_CollectForErpSync.retrieveAndClear();
        if (opportunityIds.isEmpty()) {
            // This DML operation involved no opportunity needing an ERP sync
            // (possibly not even an Opportunity DML): no job at all.
            return;
        }
        System.enqueueJob(new OpportunityErpSyncJob(opportunityIds));
    }
}
