/**
 * @description Trigger Action for the Trigger Actions Framework (Contact, before insert /
 *              before update). Enforces the rule that two Contacts of the same Account may
 *              not share an email address, compared case-insensitively.
 *
 *              - Contacts without an Account or without an Email are not checked.
 *              - A violating contact receives a record-level error; valid contacts in the
 *                same save are unaffected (partial saves work).
 *              - Within a single save, the first contact for a given (Account, Email) pair
 *                is accepted and each later one is rejected.
 *              - On update, only contacts whose Email or AccountId changed are checked, and
 *                a contact never conflicts with itself.
 *              - Bulk-safe: at most one SOQL query per trigger execution.
 */
public inherited sharing class TA_Contact_PreventDuplicateEmail
        implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {

    @TestVisible
    private static final String ERROR_MESSAGE =
        'Another contact on this account already uses this email address.';

    /**
     * @description Before insert: check every contact that has both an Account and an Email.
     */
    public void beforeInsert(List<SObject> triggerNew) {
        validate((List<Contact>) triggerNew, new Set<Id>());
    }

    /**
     * @description Before update: only check contacts whose Email or AccountId changed.
     *              Their own Ids are excluded from the database lookup so a contact can
     *              never conflict with itself (legacy duplicates stay untouched).
     */
    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Map<Id, SObject> oldMap = new Map<Id, SObject>(triggerOld);
        List<Contact> changedContacts = new List<Contact>();

        for (SObject record : triggerNew) {
            Contact newContact = (Contact) record;
            Contact oldContact = (Contact) oldMap.get(newContact.Id);
            if (newContact.Email != oldContact.Email
                    || newContact.AccountId != oldContact.AccountId) {
                changedContacts.add(newContact);
            }
        }

        validate(changedContacts, oldMap.keySet());
    }

    /**
     * @description Shared validation logic. Runs exactly one SOQL query, collecting only
     *              the relevant Accounts and Emails from the records being checked, then
     *              evaluates the records in list order so the first occurrence of a
     *              (AccountId, Email) pair wins and later duplicates get a record error.
     * @param candidates   Contacts to validate (already context-filtered).
     * @param idsToExclude Ids that must not be matched against the database (the contacts
     *                     being updated themselves, so they cannot conflict with themselves).
     */
    private void validate(List<Contact> candidates, Set<Id> idsToExclude) {
        if (candidates == null || candidates.isEmpty()) {
            return;
        }

        List<Contact> toCheck = new List<Contact>();
        Set<Id> accountIds = new Set<Id>();
        Set<String> emails = new Set<String>();

        for (Contact candidate : candidates) {
            if (candidate.AccountId != null && String.isNotBlank(candidate.Email)) {
                toCheck.add(candidate);
                accountIds.add(candidate.AccountId);
                emails.add(candidate.Email);
            }
        }
        if (toCheck.isEmpty()) {
            return;
        }

        // Single bulkified query. SOQL string comparison is case-insensitive, and keys are
        // additionally normalized to lower case for the in-memory comparisons below.
        Map<String, Contact> existingByKey = new Map<String, Contact>();
        for (Contact existing : [
            SELECT Id, AccountId, Email
            FROM Contact
            WHERE AccountId IN :accountIds
              AND Email IN :emails
              AND Id NOT IN :idsToExclude
        ]) {
            if (existing.AccountId != null && String.isNotBlank(existing.Email)) {
                existingByKey.put(buildKey(existing.AccountId, existing.Email), existing);
            }
        }

        Set<String> keysSeenThisSave = new Set<String>();
        for (Contact toValidate : toCheck) {
            String key = buildKey(toValidate.AccountId, toValidate.Email);
            if (existingByKey.containsKey(key) || keysSeenThisSave.contains(key)) {
                toValidate.addError(ERROR_MESSAGE);
            } else {
                keysSeenThisSave.add(key);
            }
        }
    }

    /**
     * @description Case-insensitive (AccountId, Email) conflict key.
     */
    private static String buildKey(Id accountId, String email) {
        return String.valueOf(accountId) + ':' + email.toLowerCase();
    }
}
