        <value xsi:type="xsd:string">Notifies the key account team when an Account&apos;s Rating has just changed to Hot. Runs in the after update context and only receives Accounts that passed the entry criteria (new Rating is Hot and the previous Rating was not Hot).</value>
    </values>
    <values>
        <field>Entry_Criteria__c</field>
        <value xsi:type="xsd:string">newAccount.Rating = &apos;Hot&apos; &amp;&amp; oldAccount.Rating != &apos;Hot&apos;</value>
    </values>
